using System.Linq;using UnityEngine;using UnityEngine.UI;using Demo5.FrontEnd;
public static class InspectBagMask {public static string Run(){var b=Object.FindAnyObjectByType<ExpeditionBagPanel>(FindObjectsInactive.Include);return string.Join("\n",new[]{b.LeftMembers,b.RightMembers}.Select(r=>r.parent.name+" scrollviewport="+r.GetComponentInParent<ScrollRect>().viewport?.name+" parentpos="+r.parent.position+" masks="+string.Join(" / ",r.GetComponentsInParent<RectMask2D>().Select(m=>m.name+" "+m.rectTransform.rect+" padding "+m.padding))))+"\n"+string.Join("\n",b.LeftCards.Take(3).Select(c=>c.Paper.name+" enabled "+c.Paper.enabled+" alpha "+c.Paper.canvasRenderer.GetAlpha()+" cull "+c.Paper.canvasRenderer.cull+" sprite "+c.Paper.sprite+" groups "+string.Join(",",c.GetComponentsInParent<CanvasGroup>().Select(g=>g.alpha.ToString()))));}}
